const express = require('express');
const { DatabaseSync } = require('node:sqlite');
const { verifyJwt } = require('../auth/jwt');

const app = express();
app.use(express.json());
const db = new DatabaseSync('/opt/flags/cache.db');

app.put('/api/feature-flags/:flagKey/overrides', verifyJwt, (req, res) => {
  const { flagKey } = req.params;
  const { targetTenantId, enabled, rules } = req.body;

  // Enforce that administrators can only configure overrides for their own tenant
  if (req.user.role !== 'SUPER_ADMIN' && req.user.tenantId !== targetTenantId) {
    return res.status(403).json({ error: 'Access denied: Cannot configure overrides for other tenants' });
  }

  const stmt = db.prepare(`
    INSERT INTO tenant_overrides (flag_key, tenant_id, enabled, rules_json, updated_by)
    VALUES (?, ?, ?, ?, ?)
    ON CONFLICT(flag_key, tenant_id) DO UPDATE SET
      enabled = excluded.enabled,
      rules_json = excluded.rules_json,
      updated_by = excluded.updated_by
  `);

  stmt.run(flagKey, targetTenantId, enabled ? 1 : 0, JSON.stringify(rules || {}), req.user.id);
  res.json({ success: true, flagKey, targetTenantId, enabled });
});

module.exports = app;
